import type { Contracts } from "@mainsail/contracts";

import { blockHeader, blockSerialized } from "./block.js";
import { lockProof, serializedLockProof } from "./lock-proof.js";

// Scenarios:
// 1. Proposal without valid round
// 2. Proposal with valid round
// 3. Proposal without valid round, with lock proof
// 4. Proposal with valid round, with lock proof

// Names:
// 1. serializedProposal
// 2. serializedProposalWithValidRound
// 3. serializedProposalWithLockProof
// 4. serializedProposalWithValidRoundWithLockProof

// PROPOSAL WITH LOCK PROOF

export const payload: Contracts.Crypto.ProposedPayload = {
	block: {
		serialized: blockSerialized,
	},
	lockProof,
};

export const payloadSerialized = "69" + serializedLockProof + blockSerialized; // 

export const proposalDataSerializableUnsigned: Contracts.Crypto.ProposalDataSerializableUnsigned = {
	data: {
		serialized: payloadSerialized,
	},
	round: 1,
	validRound: undefined,
	validatorIndex: 0,
};

export const proposalSerializedUnsigned = "010000000011030000" + payloadSerialized + "00"; // 

export const signature = "b231316561d7846f073749fd172b22865650080ca492587510d057d268e84eef7f6c1b62bf268eb6a5719d85fe48da0c0b66f4b73490b6842f1f6090b4ee4b9c1c537726dc9b40fffc7052f35ae0499b48732aca4a6232aa4a14adf972dd1b60";

export const proposalDataSerializable: Contracts.Crypto.ProposalDataSerializable = {
	...proposalDataSerializableUnsigned,
	signature,
};

export const proposalSerialized =
	"010000000011030000" +
	payloadSerialized +
	"00" +
	signature; // 

export const proposalData: Contracts.Crypto.ProposalData = {
	...proposalDataSerializable,
	blockHeader,
	lockProof,
};
